/**
 * とにおクエスト — 「今夜も、通じない。」のサーガ(物語)レイヤー。
 *
 * ただの失敗日記では人は読まない。読者が毎回追う理由は「積み上がる数字」と
 * 「終わらない物語」。このファイルが番組のRPG世界観と、夜ごとのクエスト記録
 * (EXP/レベル/ドロップ/パーティ勤怠/次回への引き)を一元管理する。
 *
 * 鉄の掟:
 * - 証拠主義は崩さない。EXPもドロップも全部 kenshi-lessons / dmm-show の実データから。
 *   捏造していいのは「世界観の語彙」だけで、事実は捏造しない。
 * - 恥 = 経験値。ボケるほど強くなる。これが番組哲学のゲーム化。
 * - 新しい夜を dmm-show.ts に足したら、NIGHT_QUESTS にも1件足す(EXPルールは下記)。
 *
 * EXPルール(単純に保つ):
 *   レッスン完走 +100 / ボケ1本(検死掲載の実ミス) +30 / イディオム実戦着地 +50
 *   捏造語の召喚(モンスター図鑑登録) +80 / 復習ループ完成などの偉業 +50
 * レベル閾値: Lv2=200, Lv3=500, Lv4=900, Lv5=1400, Lv6=2000, Lv7=2700 (以降 +800ずつ)
 */

export interface SagaSkill {
    name: string;           // スキル名(和名)
    en: string;             // 実際に着地した英語
    acquiredNight: number;  // 習得した夜
    note: string;           // 発動条件・効果(笑い+実用)
}

export interface SagaMonster {
    name: string;           // モンスター名 = 捏造語
    summonedNight: number;  // 召喚してしまった夜
    spoke: string;          // 召喚の呪文(実際の発言)
    note: string;           // 生態
}

export interface PartyMember {
    name: string;           // 冠詞のa 等
    role: string;
    status: string;         // 最新の勤怠・状態(夜が進んだら更新)
}

export interface NightQuest {
    night: number;
    date: string;
    questName: string;      // クエスト名(RPG語彙)
    objective: string;      // その夜の実際の目標
    result: 'CLEAR' | 'CLEAR_COND' | 'FAILED';  // COND=条件付きクリア
    expGained: number;
    expBreakdown: string;   // 内訳(証拠)
    totalExp: number;       // 累計
    level: number;          // この夜終了時点のレベル
    levelUp: boolean;
    drops: string[];        // ドロップ品(スキル/図鑑登録/持ち帰り)
    partyLog: string;       // 冠詞a等の勤怠報告
    nextQuest: string;      // 次回への引き
}

